223→
224→    #[test]
225→    fn show_update_notification_with_ui() {
226→        let mut ui = MockUI::new();
227→        // This will check for updates which may or may not find anything
228→        // Mostly testing that it doesn't panic
229→        show_update_notification(&mut ui);
230→    }
